import { test, expect } from '@playwright/test';
import path from 'path';

test.describe('Transmittal App User Flow', () => {

    test.beforeEach(async ({ page }) => {
        // Clear local storage to reset "Welcome Modal" state
        await page.addInitScript(() => {
            window.localStorage.clear();
        });
    });

    test('Complete User Journey', async ({ page }) => {
        page.on('console', msg => console.log('BROWSER CONSOLE:', msg.text()));
        page.on('pageerror', err => console.log('BROWSER ERROR:', err.message));

        // 1. Visit App Dashboard (Mock Auth handles login)
        console.log('Navigating to dashboard...');
        await page.goto('/app');

        // Check title
        await expect(page).toHaveTitle(/Transmit.AI/);

        // 2. Check Welcome Modal
        console.log('Checking Welcome Modal...');
        // Wait for the modal to appear (it has a small delay)
        const welcomeModal = page.getByText(/Welcome to Transmit\.AI!/);
        // Increase timeout because of the 1.5s delay
        await expect(welcomeModal).toBeVisible({ timeout: 5000 });

        // Click Next
        await page.getByRole('button', { name: 'Next' }).click();
        // Click Next again
        await page.getByRole('button', { name: 'Next' }).click();
        // Click Let's Get Started
        await page.getByRole('button', { name: "Let's Get Started" }).click();

        // Verify Modal Closed
        await expect(welcomeModal).not.toBeVisible();

        // 3. Verify Dashboard Empty State
        console.log('Verifying Dashboard Empty State...');
        await expect(page.getByText('No documents yet')).toBeVisible();
        await expect(page.getByRole('button', { name: 'Upload Your First Document' })).toBeVisible();

        // 4. Navigate to Upload
        await page.getByRole('button', { name: 'Upload Your First Document' }).click();
        await expect(page).toHaveURL(/\/app\/upload/);

        // Check Guidance
        await expect(page.getByText('Supported Formats')).toBeVisible();

        // 5. Upload File
        console.log('Uploading file...');
        const fileInput = page.locator('input[type="file"]');
        await fileInput.setInputFiles('test-upload.pdf');

        // Verify file in list
        await expect(page.getByText('test-upload.pdf')).toBeVisible();

        // 6. Process File
        console.log('Processing file...');
        const processButton = page.getByRole('button', { name: 'Start AI Extraction' });
        await processButton.click();

        // Check loading state
        await expect(page.getByText('Processing')).toBeVisible();

        // Wait for results
        await expect(page.getByText('Extraction Results')).toBeVisible({ timeout: 15000 });

        // 7. Verify Results
        console.log('Verifying results...');
        await expect(page.getByText('test-upload.pdf')).toBeVisible();
        // Check for "AI" badge
        await expect(page.getByText('AI', { exact: true })).toBeVisible();

        // 8. Test Export
        console.log('Testing Export...');
        // There are multiple "Export Excel" buttons? No, just one in the results header.
        await page.getByRole('button', { name: 'Export Excel' }).click();

        // Verify Toast Success
        const toast = page.locator('.bg-green-50').first();
        await expect(toast).toBeVisible();
        await expect(toast).toContainText('Exported');

        // 9. Return to Dashboard and Verify Data
        console.log('Returning to Dashboard...');
        // Click logo or dashboard link?
        // Let's use the explicit "Dashboard" link in sidebar or just go back
        await page.goto('/app');

        // Verify populated dashboard
        // Should see a transmittal card
        // The default transmittal title logic might group them or put them in "Unsorted Uploads" if no title set.
        // In UploadPage we didn't set a title, so it might be "Unsorted Uploads" or empty string if logic handles it.
        // Let's check for "Docs" count or the filename in the detailed view if "Unsorted" isn't a transmittal.
        // Dashboard logic:
        // Object.entries(transmittals).map(([title, docs])
        // If title is empty/undefined, it groups by that key.

        // Let's just check that "No documents yet" is GONE.
        await expect(page.getByText('No documents yet')).not.toBeVisible();

        // 10. Test Delete
        console.log('Testing Delete...');
        // Find a delete button (trash can)
        // The dashboard has delete buttons for Transmittals AND Documents.
        // Let's delete the Transmittal (there should be one card).
        const deleteTransmittalBtn = page.locator('button[title="Delete Transmittal"]').first();
        await deleteTransmittalBtn.click();

        // Check Confirmation Modal
        const deleteModalTitle = page.locator('text=Delete Transmittal?');
        await expect(deleteModalTitle).toBeVisible();
        await expect(page.locator('text=This will delete all 1 documents')).toBeVisible();

        // Confirm Delete
        await page.getByRole('button', { name: 'Delete', exact: true }).click();

        // Verify Loading state on button? Hard to catch.
        await expect(page.locator('text=Deleted transmittal')).toBeVisible();

        // Verify Empty State Returns
        await expect(page.getByText('No documents yet')).toBeVisible();

        console.log('Test Complete!');
    });
});

import React from 'react';
import { useUser } from '@clerk/clerk-react';
import { CreditCard, ExternalLink } from 'lucide-react';
import { useDocumentStore } from '../services/store';

const BillingSettings: React.FC = () => {
    const { user } = useUser();
    const { subscriptionTier } = useDocumentStore();
    const [isLoading, setIsLoading] = React.useState(false);

    const handleManageSubscription = async () => {
        setIsLoading(true);
        try {
            const apiUrl = import.meta.env.VITE_API_URL || 'http://localhost:3000/api';
            const res = await fetch(`${apiUrl}/create-portal-session`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    userId: user?.id,
                    email: user?.primaryEmailAddress?.emailAddress,
                    returnUrl: window.location.href
                })
            });

            if (!res.ok) {
                const text = await res.text();
                throw new Error(`Server error: ${res.status} ${res.statusText} ${text.substring(0, 100)}`);
            }

            const data = await res.json();
            if (data.url) {
                window.location.href = data.url;
            } else {
                alert('Failed to open billing portal. You may not have an active subscription.');
            }
        } catch (error: any) {
            console.error('Billing Portal Error:', error);
            alert(`Error opening billing portal: ${error.message}`);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="p-8 w-full max-w-3xl">
            <h2 className="text-2xl font-bold text-slate-900 mb-6">Subscription & Billing</h2>

            {/* Current Plan Card */}
            <div className={`border rounded-xl p-6 shadow-sm mb-6 ${subscriptionTier === 'business' ? 'bg-slate-900 border-slate-900 text-white' :
                    subscriptionTier === 'pro' ? 'bg-blue-50 border-blue-100' :
                        'bg-white border-slate-200'
                }`}>
                <div className="flex justify-between items-start">
                    <div>
                        <p className={`text-sm font-medium mb-1 ${subscriptionTier === 'business' ? 'text-slate-400' : 'text-slate-500'}`}>Current Plan</p>
                        <h3 className={`text-2xl font-bold capitalize ${subscriptionTier === 'business' ? 'text-white' : 'text-slate-900'}`}>{subscriptionTier} Plan</h3>
                        <p className={`text-sm mt-2 ${subscriptionTier === 'business' ? 'text-slate-300' : 'text-slate-500'}`}>
                            {subscriptionTier === 'free' && 'Upgrade to remove limits.'}
                            {subscriptionTier === 'pro' && 'Great for individuals.'}
                            {subscriptionTier === 'business' && 'Powering your entire team.'}
                        </p>
                    </div>
                    <div className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide 
                        ${subscriptionTier === 'free' ? 'bg-slate-100 text-slate-600' :
                            subscriptionTier === 'pro' ? 'bg-blue-100 text-blue-700' :
                                'bg-yellow-400 text-slate-900'}`}>
                        {subscriptionTier}
                    </div>
                </div>
            </div>

            {/* Actions Section */}
            <div className="space-y-4">
                {/* Upgrade to Pro (Visible only for Free) */}
                {subscriptionTier === 'free' && (
                    <div className="bg-blue-50 border border-blue-100 rounded-xl p-6 flex flex-col md:flex-row items-center justify-between gap-4">
                        <div>
                            <h4 className="font-bold text-blue-900">Upgrade to Pro</h4>
                            <p className="text-sm text-blue-700 mt-1">Get 500 documents/mo and unlimited history.</p>
                        </div>
                        <button
                            onClick={() => document.dispatchEvent(new CustomEvent('open-upgrade-modal'))}
                            className="whitespace-nowrap px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg transition-colors shadow-sm"
                        >
                            Upgrade Now
                        </button>
                    </div>
                )}

                {/* Upgrade to Business (Visible for Pro) */}
                {subscriptionTier === 'pro' && (
                    <div className="bg-slate-50 border border-slate-200 rounded-xl p-6 flex flex-col md:flex-row items-center justify-between gap-4">
                        <div>
                            <h4 className="font-bold text-slate-900 flex items-center gap-2">
                                Upgrade to Business
                                <span className="text-[10px] bg-yellow-100 text-yellow-800 px-2 py-0.5 rounded-full uppercase font-bold">Recommended</span>
                            </h4>
                            <p className="text-sm text-slate-600 mt-1">Need more? Get 2,500 documents/mo and priority support.</p>
                        </div>
                        <button
                            onClick={handleManageSubscription} // Portal handles upgrades
                            disabled={isLoading}
                            className="whitespace-nowrap px-4 py-2 bg-slate-900 hover:bg-slate-800 text-white font-medium rounded-lg transition-colors shadow-sm flex items-center gap-2"
                        >
                            {isLoading ? 'Loading...' : 'Update Plan'}
                            <ExternalLink size={14} />
                        </button>
                    </div>
                )}

                {/* Manage Subscription (Visible for Paid) */}
                {subscriptionTier !== 'free' && (
                    <div className="bg-white border border-slate-200 rounded-xl p-6">
                        <h4 className="font-semibold text-slate-900 mb-2 flex items-center gap-2">
                            <CreditCard size={18} />
                            Manage Subscription
                        </h4>
                        <p className="text-slate-600 text-sm mb-4">
                            Update payment method, download invoices, or cancel subscription.
                        </p>
                        <button
                            onClick={handleManageSubscription}
                            disabled={isLoading}
                            className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 hover:bg-slate-50 text-slate-700 font-medium rounded-lg transition-colors shadow-sm"
                        >
                            {isLoading ? 'Loading...' : 'Open Customer Portal'}
                            <ExternalLink size={14} />
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default BillingSettings;

import React, { useState, useEffect } from 'react';
import { useUser } from '@clerk/clerk-react';
import { Building2, Save, X, Loader2 } from 'lucide-react';
import { useToast } from './Toast';

interface CompanySettingsProps {
    // No props needed, uses internal state/fetching
}

const CompanySettings: React.FC<CompanySettingsProps> = () => {
    const { user } = useUser();
    const { showToast } = useToast();
    const [isLoading, setIsLoading] = useState(false);

    // Form State
    const [companyName, setCompanyName] = useState('');
    const [logoUrl, setLogoUrl] = useState('');

    // Edit State
    const [isEditingName, setIsEditingName] = useState(false);
    const [isSavingName, setIsSavingName] = useState(false);
    const [isSavingLogo, setIsSavingLogo] = useState(false);

    // Fetch existing settings
    useEffect(() => {
        if (!user) return;
        const fetchSettings = async () => {
            setIsLoading(true);
            try {
                // Pass email to ensure user creation
                const email = user.primaryEmailAddress?.emailAddress;
                const url = email ? `/api/user/${user.id}?email=${encodeURIComponent(email)}` : `/api/user/${user.id}`;
                const res = await fetch(url);
                if (res.ok) {
                    const data = await res.json();
                    if (data.company_name) setCompanyName(data.company_name);
                    if (data.company_logo_url) setLogoUrl(data.company_logo_url);
                }
            } catch (error) {
                console.error('Failed to load settings:', error);
            } finally {
                setIsLoading(false);
            }
        };
        fetchSettings();
    }, [user]);

    const handleSaveName = async () => {
        if (!user) return;
        setIsSavingName(true);
        try {
            const email = user.primaryEmailAddress?.emailAddress;
            const res = await fetch(`/api/user/${user.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    company_name: companyName,
                    email // Pass email for auto-creation
                })
            });
            if (!res.ok) {
                const errorData = await res.json().catch(() => ({}));
                console.error('Save failed:', res.status, errorData);
                throw new Error(errorData.error || 'Failed to update settings');
            }
            showToast('Company name updated', 'success');
            setIsEditingName(false);
        } catch (error) {
            showToast('Failed to update name', 'error');
        } finally {
            setIsSavingName(false);
        }
    };

    const handleLogoSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (!user || !e.target.files?.[0]) return;

        const file = e.target.files[0];
        if (file.size > 500 * 1024) { // 500KB limit
            showToast('Logo must be under 500KB', 'error');
            return;
        }

        setIsSavingLogo(true);

        // Convert to Base64
        const reader = new FileReader();
        reader.onload = async (ev) => {
            if (ev.target?.result) {
                const newLogoUrl = ev.target.result as string;
                try {
                    const email = user.primaryEmailAddress?.emailAddress;
                    const res = await fetch(`/api/user/${user.id}`, {
                        method: 'PUT',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            company_logo_url: newLogoUrl,
                            email // Pass email for auto-creation
                        })
                    });

                    if (!res.ok) {
                        const errorData = await res.json().catch(() => ({}));
                        console.error('Logo upload failed:', res.status, errorData);
                        throw new Error(errorData.error || 'Failed to update settings');
                    }

                    setLogoUrl(newLogoUrl);
                    showToast('Logo updated successfully', 'success');
                } catch (error) {
                    console.error(error);
                    showToast('Failed to upload logo', 'error');
                } finally {
                    setIsSavingLogo(false);
                }
            }
        };
        reader.readAsDataURL(file);
    };

    const handleRemoveLogo = async () => {
        if (!user) return;
        if (!confirm('Are you sure you want to remove the logo?')) return;

        setIsSavingLogo(true);
        try {
            await fetch(`/api/user/${user.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ company_logo_url: '' })
            });
            setLogoUrl('');
            showToast('Logo removed', 'success');
        } catch (error) {
            showToast('Failed to remove logo', 'error');
        } finally {
            setIsSavingLogo(false);
        }
    };

    if (isLoading) {
        return (
            <div className="flex justify-center p-8">
                <Loader2 className="animate-spin text-slate-400" />
            </div>
        );
    }

    return (
        <div className="w-full max-w-3xl">
            <div className="mb-6 pb-4 border-b border-slate-200">
                <h2 className="text-xl font-bold text-slate-900">Company details</h2>
                <p className="text-sm text-slate-500 mt-1">Manage branding for exports.</p>
            </div>

            <div className="space-y-0">
                {/* Company Name Row */}
                <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between py-6 border-b border-slate-200 gap-4">
                    <div className="sm:w-1/3">
                        <label className="text-sm font-semibold text-slate-900">Company Name</label>
                    </div>

                    <div className="flex-1 w-full sm:w-auto">
                        {isEditingName ? (
                            <div className="flex items-center gap-2">
                                <input
                                    type="text"
                                    className="w-full px-3 py-1.5 border border-slate-300 rounded text-sm focus:ring-2 focus:ring-slate-900 focus:border-slate-900 outline-none"
                                    placeholder="Enter company name"
                                    value={companyName}
                                    onChange={(e) => setCompanyName(e.target.value)}
                                    autoFocus
                                />
                                <div className="flex items-center gap-1">
                                    <button
                                        onClick={handleSaveName}
                                        disabled={isSavingName}
                                        className="p-1.5 bg-slate-900 text-white rounded hover:bg-slate-800 disabled:opacity-50"
                                    >
                                        {isSavingName ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                                    </button>
                                    <button
                                        onClick={() => setIsEditingName(false)}
                                        className="p-1.5 text-slate-500 hover:text-slate-800"
                                    >
                                        <X size={16} />
                                    </button>
                                </div>
                            </div>
                        ) : (
                            <div className="flex items-center justify-between w-full">
                                <span className={companyName ? "text-sm text-slate-900" : "text-sm text-slate-400 italic"}>
                                    {companyName || 'Not set'}
                                </span>
                            </div>
                        )}
                    </div>

                    {!isEditingName && (
                        <div className="sm:w-auto">
                            <button
                                onClick={() => setIsEditingName(true)}
                                className="text-sm font-medium text-slate-500 hover:text-slate-900 transition-colors"
                            >
                                Update
                            </button>
                        </div>
                    )}
                </div>

                {/* Company Logo Row */}
                <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between py-6 border-b border-slate-200 gap-4">
                    <div className="sm:w-1/3">
                        <label className="text-sm font-semibold text-slate-900">Company Logo</label>
                    </div>

                    <div className="flex-1 flex items-center gap-4">
                        <div className="w-10 h-10 rounded-full overflow-hidden bg-slate-100 border border-slate-200 flex items-center justify-center shrink-0">
                            {logoUrl ? (
                                <img src={logoUrl} alt="Logo" className="w-full h-full object-contain p-1" />
                            ) : (
                                <Building2 className="text-slate-400" size={18} />
                            )}
                        </div>
                        <div className="flex flex-col">
                            <span className="text-sm font-medium text-slate-900">
                                {logoUrl ? 'Logo uploaded' : 'No logo set'}
                            </span>
                        </div>
                    </div>

                    <div className="sm:w-auto flex items-center gap-3">
                        {logoUrl && (
                            <button
                                onClick={handleRemoveLogo}
                                disabled={isSavingLogo}
                                className="text-sm font-medium text-red-500 hover:text-red-700 transition-colors"
                            >
                                Remove
                            </button>
                        )}

                        <div className="relative">
                            <input
                                type="file"
                                id="logo-upload-row"
                                className="hidden"
                                accept="image/*"
                                onChange={handleLogoSelect}
                                disabled={isSavingLogo}
                            />
                            <label
                                htmlFor="logo-upload-row"
                                className={`text-sm font-medium ${isSavingLogo ? 'text-slate-300' : 'text-slate-500 hover:text-slate-900'} cursor-pointer transition-colors`}
                            >
                                {isSavingLogo ? 'Uploading...' : (logoUrl ? 'Change logo' : 'Upload logo')}
                            </label>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CompanySettings;

