import { useState, useEffect, useMemo } from 'react';
import { useUser, useAuth } from '@clerk/clerk-react';
import { useDocumentStore, type DocumentData } from '../services/store';
// Lazy load heavy dependencies to reduce initial bundle size
// import ExcelJS from 'exceljs';
// import jsPDF from 'jspdf';
// import autoTable from 'jspdf-autotable';
import UpgradeModal from '../components/UpgradeModal';
import Modal from '../components/Modal';
import { Zap, Folder, Calendar, ChevronRight, ArrowLeft, Trash2, Download } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useToast } from '../components/Toast';
import LoadingSpinner from '../components/LoadingSpinner';
import WelcomeModal from '../components/WelcomeModal';

import SEO from '../components/SEO';

const Dashboard = () => {
    const { user } = useUser();
    const { getToken } = useAuth();
    const navigate = useNavigate();
    const { documents, usage, subscriptionTier, isInitialized, fetchUserStatus, fetchDocuments, deleteDocument, deleteTransmittal } = useDocumentStore();
    const { showToast } = useToast();
    const [isUpgradeModalOpen, setIsUpgradeModalOpen] = useState(false);
    const [selectedTransmittal, setSelectedTransmittal] = useState<string | null>(null);
    const [isExporting, setIsExporting] = useState(false);
    const [isDeleting, setIsDeleting] = useState(false);

    // Confirmation Modal State
    const [confirmModal, setConfirmModal] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        onConfirm: () => void;
    }>({ isOpen: false, title: '', message: '', onConfirm: () => { } });



    useEffect(() => {
        const sync = async () => {
            if (user) {
                const token = await getToken();
                // Force fetch status if not initialized yet
                if (!isInitialized) {
                    console.log('[Dashboard] Fetching user status (Fallback)...');
                    fetchUserStatus(user.id, user.primaryEmailAddress?.emailAddress, token || undefined);
                }
                fetchDocuments(user.id, token || undefined);
            }
        };
        sync();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user, isInitialized]);

    const isPro = subscriptionTier !== 'free' || usage.limit > 20;
    const documentLimit = usage.limit;
    const documentsUsed = usage.current;

    // Group Documents by Transmittal Title and sort by Discipline
    const transmittals = useMemo(() => {
        const groups: Record<string, DocumentData[]> = {};

        // Define discipline order for consistent sorting
        const disciplineOrder: Record<string, number> = {
            'Architectural': 1,
            'Structural': 2,
            'Civil': 3,
            'Mechanical': 4,
            'Electrical': 5,
            'Plumbing': 6,
            'MEP': 7,
            'Landscape': 8,
            'General': 9
        };

        documents.forEach(doc => {
            const title = doc.transmittalTitle || 'Unsorted Uploads';
            if (!groups[title]) groups[title] = [];
            groups[title].push(doc);
        });

        // Sort documents within each transmittal by discipline, then by document number
        Object.keys(groups).forEach(key => {
            groups[key].sort((a, b) => {
                const disciplineA = a.discipline || 'General';
                const disciplineB = b.discipline || 'General';
                const orderA = disciplineOrder[disciplineA] || 999;
                const orderB = disciplineOrder[disciplineB] || 999;

                // First sort by discipline
                if (orderA !== orderB) {
                    return orderA - orderB;
                }

                // Then sort by document number
                return (a.documentNumber || '').localeCompare(b.documentNumber || '');
            });
        });

        return groups;
    }, [documents]);

    const handleExport = async (docsToExport: DocumentData[], filename: string) => {
        if (!isPro) {
            setIsUpgradeModalOpen(true);
            return;
        }

        setIsExporting(true);
        try {
            // Dynamically import ExcelJS only when needed
            const ExcelJS = (await import('exceljs')).default;

            const workbook = new ExcelJS.Workbook();
            const worksheet = workbook.addWorksheet('Transmittal Register');

            // Add Title Row
            worksheet.mergeCells('A1:G1');
            const titleCell = worksheet.getCell('A1');
            titleCell.value = selectedTransmittal || 'Transmittal Register';
            titleCell.font = { size: 16, bold: true, color: { argb: 'FF1F2937' } };
            titleCell.alignment = { vertical: 'middle', horizontal: 'center' };
            titleCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF3F4F6' } };
            worksheet.getRow(1).height = 30;

            // Add Date Row
            worksheet.mergeCells('A2:G2');
            const dateCell = worksheet.getCell('A2');
            dateCell.value = `Exported: ${new Date().toLocaleDateString('en-GB')}`;
            dateCell.font = { size: 10, italic: true, color: { argb: 'FF6B7280' } };
            dateCell.alignment = { vertical: 'middle', horizontal: 'center' };
            worksheet.getRow(2).height = 20;

            // Define columns (starting at row 4)
            worksheet.columns = [
                { header: 'Doc Number', key: 'documentNumber', width: 22 },
                { header: 'Revision', key: 'revision', width: 12 },
                { header: 'Title', key: 'title', width: 45 },
                { header: 'Status', key: 'status', width: 18 },
                { header: 'Issue Date', key: 'issueDate', width: 15 },
                { header: 'Discipline', key: 'discipline', width: 18 },
                { header: 'Consultant', key: 'consultant', width: 25 },
            ];

            // Style header row (row 4)
            worksheet.getRow(4).font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 11 };
            worksheet.getRow(4).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1F2937' } };
            worksheet.getRow(4).alignment = { vertical: 'middle', horizontal: 'center' };
            worksheet.getRow(4).height = 25;
            worksheet.getRow(4).border = {
                bottom: { style: 'thick', color: { argb: 'FF374151' } }
            };

            // Sort documents by discipline
            const disciplineOrder: Record<string, number> = {
                'Architectural': 1, 'Structural': 2, 'Civil': 3, 'Mechanical': 4,
                'Electrical': 5, 'Plumbing': 6, 'MEP': 7, 'Landscape': 8, 'General': 9
            };

            const sortedDocs = [...docsToExport].sort((a, b) => {
                const disciplineA = a.discipline || 'General';
                const disciplineB = b.discipline || 'General';
                const orderA = disciplineOrder[disciplineA] || 999;
                const orderB = disciplineOrder[disciplineB] || 999;

                if (orderA !== orderB) return orderA - orderB;
                return (a.documentNumber || '').localeCompare(b.documentNumber || '');
            });

            // Group by discipline colors
            const disciplineColors: Record<string, string> = {
                'Architectural': 'FFF3E8FF', 'Structural': 'FFDBEAFE', 'Civil': 'FFFEF3C7',
                'Mechanical': 'FFBFDBFE', 'Electrical': 'FFFEF9C3', 'Plumbing': 'FFD1FAE5',
                'MEP': 'FFE0E7FF', 'Landscape': 'FFD1FAE5', 'General': 'FFF3F4F6'
            };

            // Add documents with discipline grouping
            let currentDiscipline = '';
            let currentRow = 5; // Start after header

            sortedDocs.forEach((doc, index) => {
                const discipline = doc.discipline || 'General';

                // Add discipline header if discipline changes
                if (discipline !== currentDiscipline) {
                    currentDiscipline = discipline;
                    const disciplineRow = worksheet.getRow(currentRow);
                    worksheet.mergeCells(`A${currentRow}:G${currentRow}`);
                    const disciplineCell = worksheet.getCell(`A${currentRow}`);
                    disciplineCell.value = `ΓöüΓöüΓöü ${discipline.toUpperCase()} ΓöüΓöüΓöü`;
                    disciplineCell.font = { bold: true, size: 11, color: { argb: 'FF374151' } };
                    disciplineCell.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
                    disciplineCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: disciplineColors[discipline] || 'FFF3F4F6' } };
                    disciplineRow.height = 22;
                    currentRow++;
                }

                // Add document row
                worksheet.addRow(doc);
                const row = worksheet.getRow(currentRow);

                // Zebra striping within discipline
                const isEven = (currentRow % 2 === 0);
                row.fill = {
                    type: 'pattern',
                    pattern: 'solid',
                    fgColor: { argb: isEven ? 'FFFFFFFF' : 'FFFAFAFA' }
                };

                row.alignment = { vertical: 'middle' };
                row.height = 20;
                currentRow++;
            });

            // Add borders to all data cells
            worksheet.eachRow({ includeEmpty: false }, (row, rowNumber) => {
                if (rowNumber >= 4) {
                    row.eachCell((cell) => {
                        cell.border = {
                            top: { style: 'thin', color: { argb: 'FFE5E7EB' } },
                            left: { style: 'thin', color: { argb: 'FFE5E7EB' } },
                            bottom: { style: 'thin', color: { argb: 'FFE5E7EB' } },
                            right: { style: 'thin', color: { argb: 'FFE5E7EB' } }
                        };
                    });
                }
            });

            // Freeze header rows
            worksheet.views = [{ state: 'frozen', xSplit: 0, ySplit: 4 }];

            const buffer = await workbook.xlsx.writeBuffer();
            const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
            const url = window.URL.createObjectURL(blob);
            const anchor = document.createElement('a');
            anchor.href = url;
            anchor.download = `${filename.replace(/[^a-z0-9]/gi, '_')}.xlsx`;
            anchor.click();
            window.URL.revokeObjectURL(url);

            showToast(
                `Γ£à Exported ${docsToExport.length} documents to ${filename}.xlsx`,
                'success',
                5000
            );
        } catch (error) {
            console.error('Export error:', error);
            let errorMessage = 'Failed to export Excel file. ';

            if (error instanceof Error) {
                if (error.message.includes('network') || error.message.includes('fetch')) {
                    errorMessage += 'Network error - please check your connection and try again.';
                } else if (error.message.includes('memory')) {
                    errorMessage += 'File too large. Try exporting fewer documents at once.';
                } else {
                    errorMessage += 'Please try again or contact support if the issue persists.';
                }
            } else {
                errorMessage += 'Please try again.';
            }

            showToast(errorMessage, 'error', 7000);
        } finally {
            setIsExporting(false);
        }
    };

    const handleExportPDF = async (docsToExport: DocumentData[], filename: string) => {
        if (!isPro) {
            setIsUpgradeModalOpen(true);
            return;
        }

        try {
            // Dynamically import jsPDF and autoTable only when needed
            const jsPDF = (await import('jspdf')).default;
            const autoTable = (await import('jspdf-autotable')).default;

            // Create landscape PDF for better column space
            const doc = new jsPDF({ orientation: 'landscape' });

            // Add Professional Header (landscape width = 297mm)
            doc.setFillColor(31, 41, 55); // Slate-800
            doc.rect(0, 0, 297, 35, 'F');

            doc.setTextColor(255, 255, 255);
            doc.setFontSize(18);
            doc.setFont('helvetica', 'bold');
            doc.text(selectedTransmittal || 'Transmittal Register', 105, 15, { align: 'center' });

            doc.setFontSize(10);
            doc.setFont('helvetica', 'normal');
            doc.text(`Exported: ${new Date().toLocaleDateString('en-GB')}`, 105, 22, { align: 'center' });
            doc.text(`Total Documents: ${docsToExport.length}`, 105, 28, { align: 'center' });

            doc.setTextColor(0, 0, 0); // Reset to black
            let yPos = 42;

            // Sort documents by discipline
            const disciplineOrder: Record<string, number> = {
                'Architectural': 1, 'Structural': 2, 'Civil': 3, 'Mechanical': 4,
                'Electrical': 5, 'Plumbing': 6, 'MEP': 7, 'Landscape': 8, 'General': 9
            };

            const sortedDocs = [...docsToExport].sort((a, b) => {
                const disciplineA = a.discipline || 'General';
                const disciplineB = b.discipline || 'General';
                const orderA = disciplineOrder[disciplineA] || 999;
                const orderB = disciplineOrder[disciplineB] || 999;

                if (orderA !== orderB) return orderA - orderB;
                return (a.documentNumber || '').localeCompare(b.documentNumber || '');
            });

            // Group documents by discipline
            const disciplineGroups: Record<string, DocumentData[]> = {};
            sortedDocs.forEach(doc => {
                const discipline = doc.discipline || 'General';
                if (!disciplineGroups[discipline]) disciplineGroups[discipline] = [];
                disciplineGroups[discipline].push(doc);
            });

            // Discipline colors for section headers
            const disciplineColors: Record<string, [number, number, number]> = {
                'Architectural': [243, 232, 255], 'Structural': [219, 234, 254], 'Civil': [254, 243, 199],
                'Mechanical': [191, 219, 254], 'Electrical': [254, 249, 195], 'Plumbing': [209, 250, 229],
                'MEP': [224, 231, 255], 'Landscape': [209, 250, 229], 'General': [243, 244, 246]
            };

            // Create tables per discipline
            const orderedDisciplines = Object.keys(disciplineGroups).sort((a, b) => {
                const orderA = disciplineOrder[a] || 999;
                const orderB = disciplineOrder[b] || 999;
                return orderA - orderB;
            });

            orderedDisciplines.forEach((discipline, disciplineIndex) => {
                const disciplineDocs = disciplineGroups[discipline];
                const color = disciplineColors[discipline] || [243, 244, 246];

                // Add discipline section header
                if (yPos > 250) {
                    doc.addPage();
                    yPos = 20;
                }

                doc.setFillColor(...color);
                doc.roundedRect(14, yPos, 269, 8, 1, 1, 'F');
                doc.setFontSize(11);
                doc.setFont('helvetica', 'bold');
                doc.setTextColor(55, 65, 81);
                doc.text(`${discipline.toUpperCase()}`, 16, yPos + 5.5);
                yPos += 10;

                doc.setTextColor(0, 0, 0);

                // Create table for this discipline
                const tableBody = disciplineDocs.map(d => [
                    d.documentNumber || '-',
                    d.revision || '-',
                    d.title || '-',
                    d.issueDate || '-',
                    d.status || '-',
                    d.consultant || '-'
                ]);

                autoTable(doc, {
                    startY: yPos,
                    head: [['Doc Number', 'Rev', 'Title', 'Date', 'Status', 'Consultant']],
                    body: tableBody,
                    theme: 'grid',
                    headStyles: {
                        fillColor: [31, 41, 55],
                        textColor: [255, 255, 255],
                        fontStyle: 'bold',
                        fontSize: 9,
                        halign: 'center'
                    },
                    bodyStyles: {
                        fontSize: 8,
                        cellPadding: 2
                    },
                    alternateRowStyles: {
                        fillColor: [250, 250, 250]
                    },
                    columnStyles: {
                        0: { cellWidth: 40 },   // Doc Number (wider)
                        1: { cellWidth: 18 },   // Rev
                        2: { cellWidth: 115 },  // Title (much wider for landscape!)
                        3: { cellWidth: 25 },   // Date
                        4: { cellWidth: 30 },   // Status
                        5: { cellWidth: 41 }    // Consultant (wider)
                    },
                    margin: { left: 14, right: 14 },
                    didDrawPage: (data) => {
                        // Add page footer
                        const pageCount = (doc as any).internal.getNumberOfPages();
                        const pageHeight = doc.internal.pageSize.height;
                        doc.setFontSize(8);
                        doc.setTextColor(128, 128, 128);
                        doc.text(`Page ${(doc as any).internal.getCurrentPageInfo().pageNumber} of ${pageCount}`, 105, pageHeight - 10, { align: 'center' });
                    }
                });

                yPos = (doc as any).lastAutoTable.finalY + 8;
            });

            const pdfFilename = `${filename.replace(/[^a-z0-9]/gi, '_')}.pdf`;
            doc.save(pdfFilename);

            showToast(
                `Γ£à Exported ${docsToExport.length} documents to ${pdfFilename}`,
                'success',
                5000
            );
        } catch (error) {
            console.error('PDF Export error:', error);
            showToast(
                'Failed to export PDF. Please try again or contact support if the issue persists.',
                'error',
                7000
            );
        } finally {
            setIsExporting(false);
        }
    };

    const handleDeleteTransmittal = (e: React.MouseEvent, title: string) => {
        e.stopPropagation();
        if (!user) return;

        setConfirmModal({
            isOpen: true,
            title: 'Delete Transmittal?',
            message: `Are you sure you want to delete "${title}"? This will delete all ${transmittals[title].length} documents inside it.`,
            onConfirm: async () => {
                setIsDeleting(true);
                try {
                    const token = await getToken();
                    await deleteTransmittal(title, user.id, token || window.localStorage.getItem('clerk-db-jwt') || undefined);
                    if (selectedTransmittal === title) setSelectedTransmittal(null);
                    showToast(`Deleted transmittal "${title}"`, 'success');
                    setConfirmModal(prev => ({ ...prev, isOpen: false }));
                } catch (error) {
                    console.error('Delete error:', error);
                    showToast('Failed to delete transmittal', 'error');
                } finally {
                    setIsDeleting(false);
                }
            }
        });
    };

    const handleDeleteDocument = (e: React.MouseEvent, id: string, docNum: string) => {
        e.stopPropagation();
        if (!user) return;

        setConfirmModal({
            isOpen: true,
            title: 'Delete Document?',
            message: `Are you sure you want to delete document "${docNum}"?`,
            onConfirm: async () => {
                setIsDeleting(true);
                try {
                    const token = await getToken();
                    await deleteDocument(id, user.id, token || window.localStorage.getItem('clerk-db-jwt') || undefined);
                    showToast(`Deleted document "${docNum}"`, 'success');
                    setConfirmModal(prev => ({ ...prev, isOpen: false }));
                } catch (error) {
                    console.error('Delete error:', error);
                    showToast('Failed to delete document', 'error');
                } finally {
                    setIsDeleting(false);
                }
            }
        });
    };

    const [isRenaming, setIsRenaming] = useState(false);
    const [newTransmittalName, setNewTransmittalName] = useState('');

    const handleRenameTransmittal = async () => {
        if (!selectedTransmittal || !newTransmittalName.trim() || newTransmittalName === selectedTransmittal) {
            setIsRenaming(false);
            return;
        }

        try {
            const response = await fetch('/api/transmittals/rename?userId=' + user?.id, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ oldTitle: selectedTransmittal, newTitle: newTransmittalName.trim() })
            });

            const data = await response.json();

            if (response.ok) {
                if (data.count === 0) {
                    showToast('No documents were updated. Please refresh and try again.', 'error');
                } else {
                    // Optimistic update
                    fetchDocuments(user!.id); // Refetch to sync state
                    setSelectedTransmittal(newTransmittalName.trim());
                    showToast(`Renamed transmittal to "${newTransmittalName.trim()}"`, 'success');
                }
            } else {
                showToast(data.error || 'Failed to rename transmittal', 'error');
            }
        } catch (error) {
            console.error('Rename error:', error);
            showToast('Network error while renaming transmittal', 'error');
        } finally {
            setIsRenaming(false);
        }
    };

    return (
        <div className="space-y-6">
            <SEO title={selectedTransmittal ? `${selectedTransmittal} | Dashboard` : "Dashboard"} />
            <WelcomeModal />
            <UpgradeModal isOpen={isUpgradeModalOpen} onClose={() => setIsUpgradeModalOpen(false)} />

            <Modal
                isOpen={confirmModal.isOpen}
                onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })}
                title={confirmModal.title}
                message={confirmModal.message}
                type="danger"
                onConfirm={confirmModal.onConfirm}
                confirmText="Delete"
                isLoading={isDeleting}
            />

            {/* Header */}
            <header className="flex justify-between items-end">
                <div>
                    {selectedTransmittal ? (
                        <div className="flex items-center gap-2 mb-1">
                            <button
                                onClick={() => setSelectedTransmittal(null)}
                                className="text-slate-500 hover:text-slate-800 transition-colors flex items-center gap-1 text-sm font-medium"
                            >
                                <ArrowLeft size={16} /> Back to Transmittals
                            </button>
                        </div>
                    ) : (
                        <h1 className="text-3xl font-bold text-slate-900">Transmittal Register</h1>
                    )}

                    <div className="flex items-center gap-3">
                        {isRenaming && selectedTransmittal ? (
                            <div className="flex items-center gap-2 mt-2">
                                <input
                                    type="text"
                                    value={newTransmittalName}
                                    onChange={(e) => setNewTransmittalName(e.target.value)}
                                    className="text-2xl font-bold text-slate-900 border-b-2 border-blue-500 focus:outline-none bg-transparent px-1 py-0.5 w-[400px]"
                                    autoFocus
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') handleRenameTransmittal();
                                        if (e.key === 'Escape') setIsRenaming(false);
                                    }}
                                />
                                <button
                                    onClick={handleRenameTransmittal}
                                    className="bg-blue-600 text-white px-3 py-1 rounded-md text-sm font-bold hover:bg-blue-700"
                                >
                                    Save
                                </button>
                                <button
                                    onClick={() => setIsRenaming(false)}
                                    className="text-slate-500 hover:text-slate-700 text-sm font-medium"
                                >
                                    Cancel
                                </button>
                            </div>
                        ) : (
                            <h2 className={`font-bold text-slate-900 flex items-center gap-3 group ${selectedTransmittal ? 'text-3xl' : 'text-xl text-slate-500 font-normal mt-2'}`}>
                                {selectedTransmittal || 'Manage and track all project documentation'}
                                {selectedTransmittal && (
                                    <button
                                        onClick={() => {
                                            setNewTransmittalName(selectedTransmittal);
                                            setIsRenaming(true);
                                        }}
                                        className="opacity-0 group-hover:opacity-100 transition-opacity p-1.5 hover:bg-slate-100 rounded-full text-slate-400 hover:text-blue-600"
                                        title="Rename Transmittal"
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z" /><path d="m15 5 4 4" /></svg>
                                    </button>
                                )}
                            </h2>
                        )}
                    </div>
                </div>
                <div className="flex gap-3">
                    {/* Show export buttons ONLY when viewing a specific transmittal */}
                    {selectedTransmittal && (
                        <>
                            <button
                                onClick={() => handleExport(transmittals[selectedTransmittal], selectedTransmittal)}
                                disabled={isExporting}
                                className={`px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 font-medium flex items-center gap-2 transition-all shadow-md ${isExporting ? 'opacity-50 cursor-not-allowed' : ''}`}
                            >
                                {isExporting ? (
                                    <>
                                        <LoadingSpinner size="small" />
                                        Exporting...
                                    </>
                                ) : (
                                    <>
                                        <Download size={16} />
                                        Export Excel
                                        {!isPro && <Zap size={14} className="text-amber-300 fill-amber-300" />}
                                    </>
                                )}
                            </button>
                            <button
                                onClick={() => handleExportPDF(transmittals[selectedTransmittal], selectedTransmittal)}
                                disabled={isExporting}
                                className={`px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 font-medium flex items-center gap-2 transition-all shadow-md ${isExporting ? 'opacity-50 cursor-not-allowed' : ''}`}
                            >
                                {isExporting ? (
                                    <>
                                        <LoadingSpinner size="small" />
                                        Exporting...
                                    </>
                                ) : (
                                    <>
                                        <Download size={16} />
                                        Export PDF
                                        {!isPro && <Zap size={14} className="text-amber-300 fill-amber-300" />}
                                    </>
                                )}
                            </button>
                        </>
                    )}
                    {/* Show New Transmittal button ONLY on main dashboard */}
                    {!selectedTransmittal && (
                        <button
                            onClick={() => navigate('/app/upload')}
                            className="px-4 py-2 bg-slate-900 text-white rounded-lg hover:bg-slate-800 font-medium shadow-lg shadow-slate-200 transition-all"
                        >
                            New Transmittal
                        </button>
                    )}
                </div>
            </header>

            {/* Transmittal Grid View */}
            {!selectedTransmittal && (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {/* Plan Usage Card */}
                    <div
                        className={`p-6 rounded-xl shadow-lg relative overflow-hidden group cursor-pointer transition-all ${isPro ? 'bg-gradient-to-br from-slate-900 to-slate-800 text-white border border-slate-700' : 'bg-slate-900 text-white'}`}
                        onClick={() => !isPro && setIsUpgradeModalOpen(true)}
                    >
                        <div className="absolute top-0 right-0 p-2 opacity-10 group-hover:opacity-20 transition-opacity">
                            <Zap size={80} />
                        </div>
                        <div className="flex justify-between items-start mb-2">
                            <div>
                                <p className="text-slate-400 text-sm font-medium mb-1">Current Plan</p>
                                <h3 className="text-2xl font-bold flex items-center gap-2">
                                    {isPro ? 'Pro Plan' : 'Free Plan'}
                                    {isPro && <span className="bg-blue-500 text-white text-xs px-2 py-0.5 rounded-full">ACTIVE</span>}
                                </h3>
                            </div>
                            {isPro && <Zap className="text-blue-400 fill-blue-400" size={24} />}
                        </div>

                        <div className="mt-4">
                            {/* Usage Alert */}
                            {documentsUsed >= documentLimit * 0.8 && !isPro && (
                                <div className={`mb-4 p-3 rounded-lg border-2 ${documentsUsed >= documentLimit
                                    ? 'bg-red-50 border-red-300'
                                    : 'bg-orange-50 border-orange-300'
                                    }`}>
                                    <div className="flex items-center gap-2 mb-1.5">
                                        <Zap size={18} className={`shrink-0 ${documentsUsed >= documentLimit
                                            ? 'text-red-600 fill-red-600'
                                            : 'text-orange-600 fill-orange-600'
                                            }`} />
                                        <p className={`text-sm font-bold ${documentsUsed >= documentLimit
                                            ? 'text-red-900'
                                            : 'text-orange-900'
                                            }`}>
                                            {documentsUsed >= documentLimit ? 'Limit Reached!' : 'Approaching Limit'}
                                        </p>
                                    </div>
                                    <p className={`text-sm leading-snug ${documentsUsed >= documentLimit
                                        ? 'text-red-800'
                                        : 'text-orange-800'
                                        }`}>
                                        You've used <span className="font-bold">{documentsUsed} of {documentLimit}</span> documents this month.
                                        {documentsUsed >= documentLimit && ' Upgrade to continue.'}
                                    </p>
                                </div>
                            )}

                            <div className="flex justify-between items-end mb-2">
                                <span className="text-sm text-slate-300">Monthly Usage</span>
                                <span className={`font-bold ${documentsUsed >= documentLimit ? 'text-red-400' : 'text-white'}`}>
                                    {documentsUsed} / {documentLimit}
                                </span>
                            </div>
                            <div className="w-full bg-slate-700 h-2 rounded-full overflow-hidden">
                                <div
                                    className={`h-full transition-all duration-500 ${isPro ? 'bg-green-500'
                                        : documentsUsed >= documentLimit ? 'bg-red-500'
                                            : documentsUsed >= documentLimit * 0.8 ? 'bg-amber-500'
                                                : 'bg-blue-500'
                                        }`}
                                    style={{ width: `${Math.min((documentsUsed / documentLimit) * 100, 100)}%` }}
                                />
                            </div>
                            <p className="text-xs text-slate-400 mt-2">
                                {isPro ? 'Unlimited documents & exports included' : 'Upgrade for unlimited documents'}
                            </p>
                        </div>
                    </div>

                    {Object.entries(transmittals).map(([title, docs]) => (
                        <div
                            key={title}
                            onClick={() => setSelectedTransmittal(title)}
                            className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all cursor-pointer group relative"
                        >
                            <div className="flex justify-between items-start mb-4">
                                <div className="p-3 bg-blue-50 text-blue-600 rounded-lg group-hover:bg-blue-100 transition-colors">
                                    <Folder size={24} />
                                </div>
                                <div className="flex gap-2">
                                    <span className="text-xs font-semibold bg-slate-100 text-slate-600 px-2 py-1 rounded-full border border-slate-200">
                                        {docs.length} Docs
                                    </span>
                                    <button
                                        onClick={(e) => handleDeleteTransmittal(e, title)}
                                        className="p-1 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded transition-all"
                                        title="Delete Transmittal"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            </div>
                            <h3 className="text-lg font-bold text-slate-900 mb-1 line-clamp-1" title={title}>{title}</h3>
                            <div className="flex items-center gap-2 text-sm text-slate-500 mb-4">
                                <Calendar size={14} />
                                <span>{new Date(docs[0].uploadedAt).toLocaleDateString()}</span>
                            </div>
                            <div className="w-full pt-4 border-t border-slate-100 flex justify-between items-center">
                                <span className="text-sm font-medium text-slate-600">View Files</span>
                                <ChevronRight size={16} className="text-slate-400 group-hover:text-blue-600 transition-colors" />
                            </div>
                        </div>
                    ))}

                    {Object.keys(transmittals).length === 0 && (
                        <div className="col-span-1 md:col-span-2 lg:col-span-3 border-2 border-dashed border-slate-200 rounded-2xl p-12 flex flex-col items-center text-center bg-slate-50/50">
                            <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center mb-6">
                                <Folder size={40} className="text-blue-600" />
                            </div>
                            <h3 className="text-xl font-bold text-slate-900 mb-2">No documents yet</h3>
                            <p className="text-slate-500 max-w-md mb-8">
                                Upload your construction drawings, transmittals, or document registers to automatically extract data.
                            </p>

                            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-2xl w-full mb-8 text-left">
                                <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                                    <div className="p-2 bg-green-50 w-fit rounded-lg mb-3">
                                        <Zap size={20} className="text-green-600" />
                                    </div>
                                    <h4 className="font-semibold text-slate-800 mb-1">AI Extraction</h4>
                                    <p className="text-xs text-slate-500">Auto-detects document numbers, revisions, and titles.</p>
                                </div>
                                <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                                    <div className="p-2 bg-blue-50 w-fit rounded-lg mb-3">
                                        <Folder size={20} className="text-blue-600" />
                                    </div>
                                    <h4 className="font-semibold text-slate-800 mb-1">Smart Sorting</h4>
                                    <p className="text-xs text-slate-500">Groups documents into transmittal packages automatically.</p>
                                </div>
                                <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                                    <div className="p-2 bg-purple-50 w-fit rounded-lg mb-3">
                                        <Download size={20} className="text-purple-600" />
                                    </div>
                                    <h4 className="font-semibold text-slate-800 mb-1">Easy Export</h4>
                                    <p className="text-xs text-slate-500">Export to Excel or PDF with a single click.</p>
                                </div>
                            </div>

                            <button
                                onClick={() => navigate('/app/upload')}
                                className="px-6 py-3 bg-blue-600 text-white rounded-xl font-semibold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200 flex items-center gap-2"
                            >
                                <Download size={20} className="rotate-180" />
                                Upload Your First Document
                            </button>
                        </div>
                    )}
                </div>
            )}

            {/* Detailed Document View */}
            {selectedTransmittal && (
                <div className="bg-white border boundary-slate-200 rounded-xl shadow-sm overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="bg-slate-50 border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500">
                                    <th className="px-6 py-3 font-semibold">Number</th>
                                    <th className="px-6 py-3 font-semibold">Rev</th>
                                    <th className="px-6 py-3 font-semibold">Title</th>
                                    <th className="px-6 py-3 font-semibold">Date</th>
                                    <th className="px-6 py-3 font-semibold">Status</th>
                                    <th className="px-6 py-3 font-semibold text-right">Action</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {transmittals[selectedTransmittal]?.map((doc) => (
                                    <tr key={doc.id} className="hover:bg-slate-50/50 transition-colors group">
                                        <td className="px-6 py-3 font-medium text-slate-900">{doc.documentNumber}</td>
                                        <td className="px-6 py-3 text-slate-600">{doc.revision}</td>
                                        <td className="px-6 py-3 text-slate-900">{doc.title}</td>
                                        <td className="px-6 py-3 text-slate-500 text-sm">{doc.issueDate}</td>
                                        <td className="px-6 py-3">
                                            <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-green-100 text-green-800">
                                                {doc.status}
                                            </span>
                                        </td>
                                        <td className="px-6 py-3 text-right">
                                            <button
                                                onClick={(e) => handleDeleteDocument(e, doc.id, doc.documentNumber)}
                                                className="text-slate-400 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-opacity"
                                                title="Delete Document"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { useUser } from '@clerk/clerk-react';
import { Upload, X, File, FileText, FileSpreadsheet, FileImage, FileCode, CheckCircle, AlertCircle, Eye, Download, Edit2, Save, RotateCcw, FileCheck, ShieldCheck, Zap } from 'lucide-react';
import { useDocumentStore } from '../services/store';
// Lazy load heavy dependencies to reduce initial bundle size
// import jsPDF from 'jspdf';
// import autoTable from 'jspdf-autotable';
// import ExcelJS from 'exceljs';
import Modal from '../components/Modal';
import UpgradeModal from '../components/UpgradeModal';
import SEO from '../components/SEO';
import { useToast } from '../components/Toast';
import LoadingSpinner from '../components/LoadingSpinner';

interface ExtractedData {
    documentNumber?: string;
    revision?: string;
    title?: string;
    issueDate?: string;
    discipline?: string;
    consultant?: string;
    summary?: string;
    documentType?: string;
    status?: string;
}

interface ResultItem {
    id: string;
    filename: string;
    data: ExtractedData;
    file: File;
    isEditing: boolean;
}

const UploadPage = () => {
    const { user } = useUser();
    const { showToast } = useToast();
    const { /* fetchUserStatus */ } = useDocumentStore();
    // Global sync in App.tsx handles the initial fetch now.
    // We only need to worry about local state here.

    // ... rest of state ...
    const [isDragging, setIsDragging] = useState(false);
    const [files, setFiles] = useState<File[]>([]);
    const [isUploading, setIsUploading] = useState(false);
    const [results, setResults] = useState<ResultItem[]>([]);
    const [error, setError] = useState<string | null>(null);
    const [uploadErrors, setUploadErrors] = useState<{ filename: string; reason: string }[]>([]); // New consolidated error state
    const [transmittalTitle, setTransmittalTitle] = useState('');
    const [isUpgradeModalOpen, setIsUpgradeModalOpen] = useState(false);

    // Company Settings
    const [companySettings, setCompanySettings] = useState<{ name?: string, logo?: string }>({});

    useEffect(() => {
        if (!user) return;
        const email = user.primaryEmailAddress?.emailAddress;
        fetch(`/api/user/${user.id}${email ? `?email=${email}` : ''}`)
            .then(res => res.json())
            .then(data => {
                setCompanySettings({
                    name: data.company_name,
                    logo: data.company_logo_url
                });
            })
            .catch(err => console.error('Failed to load company settings:', err));
    }, [user]);

    // Modal State
    const [modalConfig, setModalConfig] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        type?: 'info' | 'danger' | 'success';
        onConfirm?: () => void;
        confirmText?: string;
    }>({
        isOpen: false,
        title: '',
        message: ''
    });

    const showModal = (title: string, message: string, type: 'info' | 'danger' | 'success' = 'info', onConfirm?: () => void, confirmText?: string) => {
        setModalConfig({
            isOpen: true,
            title,
            message,
            type,
            onConfirm,
            confirmText
        });
    };

    const closeModal = () => {
        setModalConfig(prev => ({ ...prev, isOpen: false }));
    };

    const handleDrag = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setIsDragging(true);
        } else if (e.type === "dragleave") {
            setIsDragging(false);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragging(false);
        if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
            const newFiles = Array.from(e.dataTransfer.files);
            setFiles(prev => [...prev, ...newFiles]);
            setError(null);
        }
    };

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            const newFiles = Array.from(e.target.files);
            setFiles(prev => [...prev, ...newFiles]);
            setError(null);
        }
    };

    const removeFile = (name: string) => {
        setFiles(files.filter(f => f.name !== name));
    }

    const { setUsage } = useDocumentStore();

    const processFiles = async () => {
        if (!user) {
            showModal('Authentication Required', 'Please sign in to upload documents.', 'danger');
            return;
        }

        setIsUploading(true);
        setIsUploading(true);
        setError(null);
        setUploadErrors([]); // Clear previous batch errors
        const newResults: ResultItem[] = [];

        // Generate Batch Title ONCE for all files
        const batchTitle = transmittalTitle.trim() || `Transmittal - ${new Date().toLocaleString()}`;

        for (const file of files) {
            const formData = new FormData();
            // Append text fields FIRST for Multer compatibility
            formData.append('userId', user.id);
            if (user.primaryEmailAddress?.emailAddress) {
                formData.append('email', user.primaryEmailAddress.emailAddress);
            }
            formData.append('transmittalTitle', batchTitle);

            // Append File LAST
            formData.append('file', file);

            try {
                const response = await fetch('/api/documents/upload', {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${window.localStorage.getItem('clerk-db-jwt') || 'mock_token'}` // fallback for e2e
                    },
                    body: formData,
                });

                if (!response.ok) {
                    const errorData = await response.json().catch(() => ({}));

                    // Handle Specific Error Cases
                    if (response.status === 409) {
                        showToast(`Skipped duplicate: ${file.name}`, 'info');
                        throw new Error(`Duplicate file skipped: ${file.name}`);
                    }
                    if (response.status === 400) {
                        showToast(`Corrupt file detected: ${file.name}`, 'error');
                        throw new Error(`Corrupt/Invalid file: ${file.name}. ${errorData.message || ''}`);
                    }

                    const msg = errorData.details
                        ? `${errorData.error}: ${errorData.details}`
                        : (errorData.error || `Failed to upload ${file.name}`);
                    throw new Error(msg);
                }

                const json = await response.json();

                // Update Usage Store
                if (json.usage) {
                    setUsage(json.usage.current, json.usage.limit);
                }

                newResults.push({
                    id: Math.random().toString(36).substr(2, 9),
                    filename: file.name,
                    data: json.data,
                    file: file,
                    isEditing: false
                });
            } catch (err: any) {
                console.error(err);

                // Add to error list for this batch
                setUploadErrors(prev => [...prev, {
                    filename: file.name,
                    reason: err.message || 'Unknown error'
                }]);
            }
        }

        setResults(prev => [...prev, ...newResults]);
        setFiles([]); // Clear queue after processing
        setIsUploading(false);
    };

    const handlePreview = (file: File) => {
        const url = URL.createObjectURL(file);
        window.open(url, '_blank');
    };

    const handleEditToggle = (id: string) => {
        setResults(results.map(r => r.id === id ? { ...r, isEditing: !r.isEditing } : r));
    };

    const handleDataChange = (id: string, field: keyof ExtractedData, value: string) => {
        setResults(results.map(r => r.id === id ? { ...r, data: { ...r.data, [field]: value } } : r));
    };

    const handleExportExcel = async () => {
        try {
            // Dynamically import ExcelJS only when needed
            const ExcelJS = (await import('exceljs')).default;

            const workbook = new ExcelJS.Workbook();
            const worksheet = workbook.addWorksheet('Extracted Data');

            // Add Transmittal Title if exists
            let currentRow = 1;

            // Add Company Logo/Name if present
            if (companySettings.name || companySettings.logo) {
                // If we have a logo, we can add it (ExcelJS supports images)
                // For MVP, just putting Company Name in big text at A1
                if (companySettings.name) {
                    worksheet.mergeCells('A1:B1');
                    const cell = worksheet.getCell('A1');
                    cell.value = companySettings.name;
                    cell.font = { bold: true, size: 16, color: { argb: 'FF2563EB' } }; // Blue color
                    currentRow += 2;
                }
            }

            if (transmittalTitle) {
                worksheet.getRow(currentRow).values = [transmittalTitle];
                worksheet.getCell(`A${currentRow}`).font = { bold: true, size: 14 };
                worksheet.mergeCells(`A${currentRow}:I${currentRow}`); // Merge across 9 columns
                currentRow += 2; // Leave a blank row
            }

            worksheet.getRow(currentRow).values = ['Filename', 'Type', 'Document Number', 'Revision', 'Title', 'Issue Date', 'Discipline', 'Consultant', 'Summary'];
            worksheet.getRow(currentRow).font = { bold: true };

            // Define Columns (for width only)
            worksheet.columns = [
                { key: 'filename', width: 30 },
                { key: 'type', width: 10 },
                { key: 'documentNumber', width: 20 },
                { key: 'revision', width: 10 },
                { key: 'title', width: 40 },
                { key: 'issueDate', width: 15 },
                { key: 'discipline', width: 15 },
                { key: 'consultant', width: 20 },
                { key: 'summary', width: 50 },
            ];

            results.forEach(r => {
                worksheet.addRow([
                    r.filename,
                    r.filename.split('.').pop()?.toUpperCase() || '',
                    r.data.documentNumber || '',
                    r.data.revision || '',
                    r.data.title || '',
                    r.data.issueDate || '',
                    r.data.discipline || '',
                    r.data.consultant || '',
                    r.data.summary || ''
                ]);
            });

            const buffer = await workbook.xlsx.writeBuffer();
            const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            // Use transmittal title for filename if available
            a.download = transmittalTitle ? `${transmittalTitle.replace(/[^a-z0-9]/gi, '_')}.xlsx` : 'extracted_data.xlsx';
            a.click();
            URL.revokeObjectURL(url);

            showToast(
                `Γ£à Exported ${results.length} documents to ${transmittalTitle ? `${transmittalTitle.replace(/[^a-z0-9]/gi, '_')}.xlsx` : 'extracted_data.xlsx'}`,
                'success',
                5000
            );
        } catch (error) {
            console.error('Excel export error:', error);
            showToast(
                'Failed to export Excel file. Please try again or contact support.',
                'error',
                7000
            );
        }
    };



    const handleExportPDF = async () => {
        try {
            // Dynamically import jsPDF and autoTable only when needed
            const jsPDF = (await import('jspdf')).default;
            const autoTable = (await import('jspdf-autotable')).default;

            const doc = new jsPDF();
            let yPos = 15;

            // Add Transmittal Title
            // Add Header with Company Info
            if (companySettings.logo) {
                try {
                    doc.addImage(companySettings.logo, 'PNG', 160, 10, 30, 15); // Top Right Logo
                } catch (e) {
                    console.warn('Failed to add logo to PDF', e);
                }
            }

            if (companySettings.name) {
                doc.setFontSize(20);
                doc.setTextColor(37, 99, 235); // Blue
                doc.text(companySettings.name, 14, 20);
                doc.setTextColor(0, 0, 0); // Reset
                yPos = 35;
            }

            // Add Transmittal Title
            if (transmittalTitle) {
                doc.setFontSize(14);
                doc.text(transmittalTitle, 14, yPos);
                yPos += 10;
                doc.setFontSize(10); // Reset for table
            }

            const tableBody = results.map(r => [
                r.filename,
                r.filename.split('.').pop()?.toUpperCase() || '',
                r.data.documentNumber || '',
                r.data.revision || '',
                r.data.title || '',
                r.data.issueDate || '',
                r.data.discipline || '',
                r.data.consultant || ''
            ]);

            autoTable(doc, {
                startY: yPos,
                head: [['Filename', 'Type', 'Doc Num', 'Rev', 'Title', 'Date', 'Disc', 'Cons']],
                body: tableBody,
            });

            const filename = transmittalTitle ? `${transmittalTitle.replace(/[^a-z0-9]/gi, '_')}.pdf` : 'extracted_data.pdf';
            doc.save(filename);

            showToast(
                `Γ£à Exported ${results.length} documents to ${filename}`,
                'success',
                5000
            );
        } catch (error) {
            console.error('PDF export error:', error);
            showToast(
                'Failed to export PDF. Please try again or contact support.',
                'error',
                7000
            );
        }
    };



    const handleStartOver = () => {
        showModal(
            'Clear Results',
            'Are you sure you want to clear all current results? This cannot be undone.',
            'danger',
            () => {
                setResults([]);
                setFiles([]);
                setError(null);
            },
            'Yes, Clear All'
        );
    };

    return (
        <div className="max-w-6xl mx-auto space-y-8 pb-12">
            <SEO title="Upload Documents | Transmit.AI" />
            <Modal
                isOpen={modalConfig.isOpen}
                onClose={closeModal}
                title={modalConfig.title}
                message={modalConfig.message}
                type={modalConfig.type}
                onConfirm={modalConfig.onConfirm}
                confirmText={modalConfig.confirmText}
            />
            <UpgradeModal isOpen={isUpgradeModalOpen} onClose={() => setIsUpgradeModalOpen(false)} />

            <header className="mb-8">
                <h1 className="text-3xl font-bold text-slate-900">Upload Documents</h1>
                <p className="text-slate-500 mt-2">
                    Intelligent metadata extraction for Engineering, Construction, and Technical Documentation.
                </p>

                {/* Upload Guidance */}
                <div className="mt-6 bg-slate-50 rounded-xl p-5 border border-slate-100 flex flex-col md:flex-row gap-6 text-sm">
                    <div className="flex-1">
                        <h4 className="font-semibold text-slate-800 mb-2 flex items-center gap-2">
                            <FileCheck size={16} className="text-blue-600" /> Supported Formats
                        </h4>
                        <p className="text-slate-600 leading-relaxed">
                            We support <span className="font-medium text-slate-800">PDF, Word (DOCX), Excel (XLSX), Images (JPG, PNG), CAD files (DXF), Text (TXT), and CSV.</span>
                        </p>
                    </div>
                    <div className="flex-1">
                        <h4 className="font-semibold text-slate-800 mb-2 flex items-center gap-2">
                            <Zap size={16} className="text-amber-500" /> Pro Tips
                        </h4>
                        <ul className="text-slate-600 space-y-1 list-disc list-inside">
                            <li>Set a Transmittal Title to organise easier</li>
                            <li>Review extracted data before exporting</li>
                        </ul>
                    </div>
                    <div className="flex-1 relative">
                        <div className="absolute left-0 top-0 bottom-0 w-px bg-slate-200 hidden md:block"></div>
                        <div className="md:pl-6">
                            <h4 className="font-semibold text-slate-800 mb-2 flex items-center gap-2">
                                <ShieldCheck size={16} className="text-green-600" /> Secure & Private
                            </h4>
                            <p className="text-slate-600">
                                Your documents are encrypted and only accessible by you.
                                We never share your data with third parties.
                            </p>
                        </div>
                    </div>
                </div>
            </header>

            {/* Upload Area */}
            <div
                className={`relative border-2 border-dashed rounded-2xl p-12 text-center transition-all duration-200 ease-in-out cursor-pointer group
                    ${isDragging
                        ? 'border-blue-500 bg-blue-50 scale-[1.01]'
                        : 'border-slate-300 hover:border-blue-400 hover:bg-slate-50 bg-white'
                    }`}
                onDragEnter={handleDrag}
                onDragLeave={handleDrag}
                onDragOver={handleDrag}
                onDrop={handleDrop}
                onClick={() => document.getElementById('fileInput')?.click()}
            >
                <input
                    type="file"
                    id="fileInput"
                    className="hidden"
                    multiple
                    onChange={handleFileSelect}
                    accept=".pdf,.png,.jpg,.jpeg,.gif,.webp,.doc,.docx,.xls,.xlsx,.txt,.csv,.dxf"
                />
                <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                    <Upload size={32} />
                </div>
                <h3 className="text-xl font-semibold text-slate-900">Drag & Drop files here</h3>
                <p className="text-slate-500 mt-2 mb-6">or click to browse from your computer</p>
                <p className="text-xs text-slate-400 uppercase tracking-wider font-semibold">PDF ΓÇó DOCX ΓÇó XLSX ΓÇó TXT ΓÇó CSV ΓÇó DXF ΓÇó Images</p>
            </div>

            {/* Error Message (Global / Limit) */}
            {error && (
                <div className="bg-red-50 text-red-600 p-4 rounded-lg flex items-center gap-3 border border-red-100">
                    <AlertCircle size={20} />
                    <div className="flex-grow">
                        <p>{error}</p>
                        {(error.includes('limit') || error.includes('Plan')) && (
                            <button
                                onClick={() => setIsUpgradeModalOpen(true)}
                                className="text-sm font-bold underline mt-1 hover:text-red-800"
                            >
                                Upgrade to Pro to process more documents.
                            </button>
                        )}
                    </div>
                </div>
            )}

            {/* Batch Upload Errors - Persistent List */}
            {uploadErrors.length > 0 && (
                <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 animate-in fade-in slide-in-from-top-4">
                    <div className="flex justify-between items-start mb-2">
                        <h4 className="font-semibold text-amber-800 flex items-center gap-2">
                            <AlertCircle size={18} />
                            {uploadErrors.length} File{uploadErrors.length > 1 ? 's' : ''} Skipped
                        </h4>
                        <button
                            onClick={() => setUploadErrors([])}
                            className="text-xs text-amber-600 hover:text-amber-800 font-medium px-2 py-1 rounded hover:bg-amber-100 transition-colors"
                        >
                            Dismiss
                        </button>
                    </div>
                    <ul className="space-y-2 text-sm">
                        {uploadErrors.map((err, idx) => (
                            <li key={idx} className="flex gap-2 text-amber-700 bg-white/50 p-2 rounded border border-amber-100/50">
                                <span className="font-medium text-slate-700 break-all min-w-[30%]">{err.filename}:</span>
                                <span className="flex-1">{err.reason}</span>
                            </li>
                        ))}
                    </ul>
                </div>
            )}

            {/* Transmittal Title Input - Moved here so it can be set BEFORE upload */}
            {files.length > 0 && (
                <div className="bg-blue-50 border border-blue-100 rounded-xl p-6 mb-8">
                    <label htmlFor="transmittalTitle" className="block text-sm font-semibold text-blue-900 mb-1">
                        Transmittal Title / Package Name (Optional)
                    </label>
                    <input
                        type="text"
                        id="transmittalTitle"
                        placeholder="e.g., P01_Structural_Package_A"
                        className="w-full px-4 py-2 rounded-lg border border-blue-200 focus:border-blue-500 focus:ring-2 focus:ring-blue-200 outline-none transition-all placeholder:text-blue-300/70 text-blue-900 font-medium"
                        value={transmittalTitle}
                        onChange={(e) => setTransmittalTitle(e.target.value)}
                    />
                    <p className="text-xs text-blue-600/80 mt-1.5 pl-1">
                        Enter a title here to group these documents together in your dashboard.
                    </p>
                </div>
            )}

            {/* Queue */}
            {files.length > 0 && (
                <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                    <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                        <h3 className="font-semibold text-slate-700">Ready to Process ({files.length})</h3>
                        <button className="text-sm text-red-500 hover:text-red-700 font-medium" onClick={() => setFiles([])}>Clear All</button>
                    </div>
                    <div className="divide-y divide-slate-100 max-h-64 overflow-y-auto">
                        {files.map((file, idx) => (
                            <div key={idx} className="px-6 py-4 flex items-center justify-between group">
                                <div className="flex items-center gap-4">
                                    <div className="p-2 bg-slate-50 rounded-lg border border-slate-100">
                                        {(() => {
                                            const ext = file.name.split('.').pop()?.toLowerCase() || '';
                                            if (['pdf'].includes(ext)) return <FileText size={24} className="text-red-500" />;
                                            if (['doc', 'docx'].includes(ext)) return <FileText size={24} className="text-blue-600" />;
                                            if (['xls', 'xlsx', 'csv'].includes(ext)) return <FileSpreadsheet size={24} className="text-green-600" />;
                                            if (['jpg', 'jpeg', 'png', 'gif', 'webp'].includes(ext)) return <FileImage size={24} className="text-purple-600" />;
                                            if (['dwg', 'dxf'].includes(ext)) return <FileCode size={24} className="text-amber-600" />;
                                            return <File size={24} className="text-slate-400" />;
                                        })()}
                                    </div>
                                    <div>
                                        <p className="text-slate-900 font-medium">{file.name}</p>
                                        <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                                    </div>
